const spools = msg.payload;
const now = new Date().toISOString();

msg.payload = spools.map(s => ({
  id: s.id,
  color_name: s.filament.name || s.filament.material || 'Unknown',
  color_hex: s.filament.color_hex ? '#' + s.filament.color_hex : '#000000',
  material: s.filament.material || '',
  remaining_weight: s.remaining_weight ?? null,
  archived: s.archived,
  synced_at: now
}));

msg.headers = {
  'apikey': env.get('SUPABASE_SERVICE_ROLE_KEY'),
  'Authorization': 'Bearer ' + env.get('SUPABASE_SERVICE_ROLE_KEY'),
  'Content-Type': 'application/json',
  'Prefer': 'resolution=merge-duplicates,return=minimal'
};

return msg;
